import iziToast from 'izitoast';
import 'izitoast/dist/css/iziToast.min.css';
import axios from 'axios';

import SimpleLightbox from 'simplelightbox/dist/simple-lightbox.esm.js';
import 'simplelightbox/dist/simple-lightbox.min.css';

const API_KEY = '38963544-7c343bd5df4ae8b0731ae7a7e';
const BASE_URL = 'https://pixabay.com/api/';

const form = document.querySelector('.search-form');
const gallery = document.querySelector('.gallery');
const loader = document.querySelector('.loader-wrapper');
const loadMoreBtn = document.querySelector('.load-more');

let lightbox;
let searchQuery = '';
let page = 1;
const perPage = 20;
const loaderDelay = 1000;
let totalHits = 0;

function initLightbox() {
  lightbox = new SimpleLightbox('.gallery a', {
    captionsData: 'alt',
    captionDelay: 250,
  });
}

function refreshLightbox() {
  if (!lightbox) {
    initLightbox();
    return;
  }

  try {
    lightbox.refresh();
  } catch {
    initLightbox();
  }
}

form.addEventListener('submit', onSearch);
loadMoreBtn.addEventListener('click', onLoadMore);

async function fetchImages(query, currentPage) {
  const response = await axios.get(BASE_URL, {
    params: {
      key: API_KEY,
      q: query,
      image_type: 'photo',
      orientation: 'horizontal',
      safesearch: true,
      page: currentPage,
      per_page: perPage,
    },
  });

  return response.data;
}

async function onSearch(event) {
  event.preventDefault();

  const query = event.target.elements.searchQuery.value.trim();

  if (!query) {
    return;
  }

  searchQuery = query;
  page = 1;

  clearGallery();
  hideLoadMoreButton();
  showLoader();
  await delay(loaderDelay);

  try {
    const data = await fetchImages(searchQuery, page);

    totalHits = data.totalHits;

    if (data.hits.length === 0) {
      iziToast.error({
        message:
          'Sorry, there are no images matching your search query. Please try again!',
        position: 'topRight',
      });

      return;
    }

    const markup = createGalleryMarkup(data.hits);
    gallery.innerHTML = markup;
    initLightbox();

    if (page < Math.ceil(totalHits / perPage)) {
      showLoadMoreButton();
    } else {
      iziToast.info({
        message: "We're sorry, but you've reached the end of search results",
        position: 'topRight',
      });
    }
  } catch (error) {
    iziToast.error({
      message: 'Something went wrong. Please try again later.',
      position: 'topRight',
    });
  } finally {
    hideLoader();
  }
}

function clearGallery() {
  gallery.innerHTML = '';
}

function showLoader() {
  loader.classList.remove('is-hidden');
}

function hideLoader() {
  loader.classList.add('is-hidden');
}

function showLoadMoreButton() {
  loadMoreBtn.classList.remove('is-hidden');
}

function hideLoadMoreButton() {
  loadMoreBtn.classList.add('is-hidden');
}

function createGalleryMarkup(images) {
  return images
    .map(image => {
      return `
        <li class="gallery-item">
          <a class="gallery-link" href="${image.largeImageURL}">
            <img
              class="gallery-image"
              src="${image.webformatURL}"
              alt="${image.tags}"
            />
          </a>
          <ul class="image-info">
            <li>
              <span>Likes</span>
              <span>${image.likes}</span>
            </li>
            <li>
              <span>Views</span>
              <span>${image.views}</span>
            </li>
            <li>
              <span>Comments</span>
              <span>${image.comments}</span>
            </li>
            <li>
              <span>Downloads</span>
              <span>${image.downloads}</span>
            </li>
          </ul>
        </li>
      `;
    })
    .join('');
}

async function onLoadMore() {
  page += 1;

  hideLoadMoreButton();
  showLoader();
  await delay(loaderDelay);

  try {
    const data = await fetchImages(searchQuery, page);

    const markup = createGalleryMarkup(data.hits);
    gallery.insertAdjacentHTML('beforeend', markup);
    refreshLightbox();
    scrollPage();

    if (page >= Math.ceil(totalHits / perPage)) {
      hideLoadMoreButton();

      iziToast.info({
        message: "We're sorry, but you've reached the end of search results",
        position: 'topRight',
      });

      return;
    }

    showLoadMoreButton();
  } catch (error) {
    iziToast.error({
      message: 'Something went wrong. Please try again later.',
      position: 'topRight',
    });
  } finally {
    hideLoader();
  }
}

function scrollPage() {
  const galleryItem = gallery.querySelector('.gallery-item');

  if (!galleryItem) {
    return;
  }

  const cardHeight = galleryItem.getBoundingClientRect().height;

  window.scrollBy({
    top: cardHeight * 2,
    behavior: 'smooth',
  });
}

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}
